from typing import List

def parse_music(music_string: str) -> List[int]:
    note_duration = {
        'o': 4,
        'o|': 2,
        '.|': 1
    }

    notes = music_string.split()
    result = []

    for note in notes:
        if note in note_duration:
            result.append(note_duration[note])

    return result

